#!/bin/bash
# =============================================================================
# AnyTool SchemaNet Evaluation (Llama-3.3-70B)
# =============================================================================
# Runs the AnyTool baseline on all 7 SchemaNet schema pairs using
# WatsonX Llama-3.3-70B. AnyTool-format data files must already exist
# in data/schemanet/anytool_format/ (generated by convert_schemanet_to_anytool.py).
#
# Datasets: bank1_bank2, imdb_sakila, cms_omop, mimic_iii_omop,
#           synthea_omop, cprd_gold_omop, cprd_aurum_omop
#
# Usage:
#   ./scripts/run_anytool_schemanet.sh
# =============================================================================

set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BASE_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"
cd "$BASE_DIR"

if [[ -f "${BASE_DIR}/.venv/bin/activate" ]]; then
    source "${BASE_DIR}/.venv/bin/activate"
fi

if [[ -f "${BASE_DIR}/.env" ]]; then
    set -a && source "${BASE_DIR}/.env" && set +a
fi

ANYTOOL_DATA="data/schemanet/anytool_format"
RESULTS_DIR="anytool/results"
mkdir -p "$RESULTS_DIR"

DATASETS=(
    "bank1_bank2"
    "imdb_sakila"
    "cms_omop"
    "mimic_iii_omop"
    "synthea_omop"
    "cprd_gold_omop"
    "cprd_aurum_omop"
)

echo "=== AnyTool SchemaNet Evaluation ==="
echo "Start: $(date)"
echo ""

for ds in "${DATASETS[@]}"; do
    echo "Processing: schemanet_$ds"

    python anytool/run_anytool_schemanet.py \
        --dataset "schemanet_$ds" \
        --data-dir "$ANYTOOL_DATA/$ds" \
        --queries-file "$ANYTOOL_DATA/$ds/schemanet_${ds}_queries.json" \
        --output "$RESULTS_DIR/schemanet_${ds}_results.json" \
        2>&1 | grep -v DeprecationWarning

    echo ""
done

echo "=== All evaluations complete ==="
echo "End: $(date)"
